/// The Player flag a form holds (RlObservation.cs:63-64).
fn form_flag_bits(active: ActiveAbility) -> u32 {
    match active {
        ActiveAbility::Missile => 16,
        ActiveAbility::Platform => 32,
        ActiveAbility::Throw => 64,
        _ => 0,
    }
}
