fn active_throw_ability(active: ActiveAbility) -> u32 {
    match active {
        ActiveAbility::Tack => ABILITY_TACK,
        ActiveAbility::Mjolnir => ABILITY_MJOLNIR,
        ActiveAbility::PokeBall => ABILITY_POKE_BALL,
        ActiveAbility::Smoke => ABILITY_SMOKE,
        _ => ABILITY_GRENADE,
    }
}

/// The serialized FirepointOffset of a gun ability's prefab.
fn gun_firepoint_offset(data: &data::RolloutData, ability: u32) -> Vec2 {
    match ability {
        ABILITY_FREEZE => data.freeze.firepoint_offset,
        ABILITY_BLINK => data.blink.firepoint_offset,
        ABILITY_GROWTH_RAY | ABILITY_SHRINK_RAY => scale_ray_data(data, ability).firepoint_offset,
        ABILITY_DUPLICATOR => data.duplicator.firepoint_offset,
        ABILITY_MAGNET => data.magnet.firepoint_offset,
        _ => Vec2::ZERO,
    }
}

fn scale_ray_data(data: &data::RolloutData, ability: u32) -> &data::ScaleRayData {
    match ability {
        ABILITY_GROWTH_RAY => &data.scale_rays.growth,
        ABILITY_SHRINK_RAY => &data.scale_rays.shrink,
        _ => unreachable!("not a scale ray"),
    }
}

/// A rider's ground that `Updater.DestroyFix` destroyed. DestroyFix only marks
/// it IsDestroyed; the pass-end drain DestroyImmediates it (Updater.cs:89-110,
/// 339-350). Until then attachedGround is not null, so an UnGround in the same
/// pass still lifts the body 0.05 off it (PlayerPhysics.cs:366-370), while one
/// on a later pass finds it null.
#[derive(Clone)]
pub struct DestroyedGround {
    /// Where it died: a Bow firing before it ungrounds still reads
    /// currentNormal off the dead body.
    pub surface: Surface,
    /// The pass an updater destroyed it in. A DetPhysics callback casualty (a
    /// BlackHole eating it) dies after every updater of its pass, so no
    /// rider's updater ever sees it before the drain.
    pub pass: Option<u32>,
}

impl DestroyedGround {
    /// attachedGround as a rider's updater sees it on `tick`'s pass: the dead
    /// body before the drain, null after.
    fn attached(&self, tick: u32) -> Option<&Surface> {
        (self.pass == Some(tick)).then_some(&self.surface)
    }
}

/// UnGround(false) from anywhere but the rider's own lost-ground check. The
/// record is spent: attachedGround is null afterwards, so no later check this
/// pass lifts the body again.
fn force_unground(
    body: &mut Player,
    lost: &mut Option<DestroyedGround>,
    platforms: &[Platform],
    tick: u32,
) {
    let lost = lost.take();
    body.force_unground(platforms, lost.as_ref().and_then(|lost| lost.attached(tick)));
}

impl AbilitylessClone {
    fn force_unground(&mut self, platforms: &[Platform], tick: u32) {
        force_unground(&mut self.base, &mut self.ground_destroyed, platforms, tick);
    }

    /// PlayerPhysics.DropPlatformTest closing a grounded Move: a platform
    /// dropping its riders ungrounds the clone and pushes it off along the
    /// normal (PlayerPhysics.cs:285-301).
    fn drop_platform_test(&mut self, platforms: &[Platform], dynamics: &[PlatformDynamics]) {
        let Some(index) = self.base.ground.and_then(|ground| {
            platforms.iter().position(|platform| platform.id == ground && platform.active)
        }) else {
            return;
        };
        let dynamics = &dynamics[index];
        if dynamics.drop_players_frames <= 0 || dynamics.dont_drop_player_id == self.base.id {
            return;
        }
        let normal = platforms[index].surface.normal(self.base.position);
        let base = &mut self.base;
        // UnGround lifts the body off the surface before the push.
        base.position += normal * Fix::from_f32(0.05);
        base.velocity += normal * dynamics.drop_force;
        base.position += base.velocity / Fix::from_int(100);
        base.grounded = false;
        base.ground = None;
        base.grounded_speed = Fix::ZERO;
        base.rotation = Fix::ZERO;
        base.up = Vec2::UP;
        self.obs_state = STATE_FALL;
        self.state_ticks = 1;
    }
}

