/// The slime hurtbox clamps an assigned Scale to its serialized bounds,
/// MinScale `(Fix)0.3f` and MaxScale 3 (Player.prefab), and its FixTransform
/// takes the clamped value. Player.Scale itself clamps to `(Fix)0.3`. The Drill
/// and Roll form colliders carry the same bounds (Drill.prefab, Roll.prefab).
fn hurtbox_scale(scale: Fix) -> Fix {
    scale.clamp(Fix::from_f32(0.3), Fix::from_int(3))
}

impl PlayerSlot {
    fn force_unground(&mut self, platforms: &[Platform], tick: u32) {
        force_unground(&mut self.base, &mut self.ground_destroyed, platforms, tick);
    }
    /// The surface of a ground an updater destroyed earlier in this pass,
    /// which attachedGround still names until the drain.
    fn dead_ground(&self, tick: u32) -> Option<&Surface> {
        self.ground_destroyed.as_ref().and_then(|lost| lost.attached(tick))
    }
    /// PlayerPhysics.Move on a grounded body whose ground was destroyed: the
    /// IsDestroyed test UnGround()s it and returns (PlayerPhysics.cs:216-219,
    /// 262-266). A ground destroyed earlier in this pass still lifts the body
    /// and nulls its rotation; returns whether that happened. A null one is
    /// left to the move helpers' missing-ground UnGround.
    fn move_off_destroyed(&mut self, tick: u32) -> bool {
        if !self.base.grounded {
            return false;
        }
        let Some(lost) = self.ground_destroyed.take() else {
            return false;
        };
        let Some(surface) = lost.attached(tick) else {
            return false;
        };
        self.base.unground_off(Some(surface), true);
        true
    }
    /// Which PlayerBody carries the rope: the slime's, or the active form's.
    fn rope_body(&self) -> usize {
        if self.active == ActiveAbility::None { 0 } else { 1 + self.active_slot }
    }

    /// `potentialCollider.Scale = Player.Scale` on a form's box, from
    /// Ability.EnterAbility and every Ability.UpdateSim (Ability.cs:105, 135).
    /// These prefabs' boxes clamp it to MinScale 0.3 and MaxScale 3.
    /// Ability.UpdateSim's OnScaleChanged: a GunTransform or MagnetGun
    /// multiplies its FirepointOffset by the change in Player.Scale since the
    /// slot's last UpdateSim.
    /// Returns the multiplier every other OnScaleChanged gets, when it fired.
    /// Ability.UpdateSim only runs while the form does, so `prevScale` keeps
    /// the scale its last run saw across exits and re-entries.
    fn on_scale_changed(&mut self) -> Option<Fix> {
        let s = self.active_slot;
        let previous = self.gun_prev_scales[s];
        if self.player_scale == previous {
            return None;
        }
        let multiplier = self.player_scale / previous;
        self.gun_firepoint_offsets[s] *= multiplier;
        self.gun_prev_scales[s] = self.player_scale;
        Some(multiplier)
    }

    fn scale_form(&mut self, extents: Vec2, radius: Fix, offset: Vec2) {
        let scale = hurtbox_scale(self.player_scale);
        self.forms[self.active_slot].set_scale_offset(scale, extents, radius, offset);
    }

    /// FixTransform.offset of slot `s`'s gun form box: as its last Scale set
    /// left it, or the authored offset at the current scale on a form never scaled.
    fn gun_offset(&self, s: usize, offset: Vec2) -> Vec2 {
        let form = &self.forms[s];
        if form.scale == Fix::ZERO { offset * self.base.scale } else { form.offset }
    }

    /// The slot whose ability prefab registered `entity`. A forced exit leaves
    /// that form's box behind after `active_slot` has moved on.
    fn entity_slot(&self, entity: usize) -> usize {
        self.form_entities.iter().position(|&e| e == entity).unwrap_or(self.active_slot)
    }

    /// GunTransform.OnEnterAbility syncs the hurtbox after SyncPhysicsTo has
    /// zeroed an airborne rotation or aligned a grounded one to the surface
    /// normal at the re-snapped position (alignRotation).
    fn sync_gun_hurtbox(&mut self, offset: Vec2, platforms: &[Platform]) {
        self.gun.collider_up = if !self.base.grounded {
            Vec2::UP
        } else if let Some(platform) = self.base.platform(platforms) {
            platform.surface.normal(self.base.position)
        } else {
            self.base.up
        };
        self.gun.hurtbox_center = self.base.position
            + self.gun.collider_up.perp_cw().complex_mul(self.gun_offset(self.active_slot, offset));
    }

    /// The per-ability field that aliases the selected form row.
    fn form_alias(&mut self, ability: u32) -> Option<&mut usize> {
        Some(match ability {
            ABILITY_DASH => &mut self.dash_entity,
            ABILITY_BOW => &mut self.bow_entity,
            ABILITY_GRENADE | ABILITY_SMOKE | ABILITY_TACK | ABILITY_MJOLNIR | ABILITY_POKE_BALL
            | ABILITY_MISSILE => &mut self.throw_entity,
            ABILITY_MINE => &mut self.mine_entity,
            ABILITY_PUSH => &mut self.push_entity,
            ABILITY_FREEZE => &mut self.freeze_entity,
            ABILITY_BLINK => &mut self.blink_entity,
            ABILITY_GROWTH_RAY => &mut self.growth_ray_entity,
            ABILITY_SHRINK_RAY => &mut self.shrink_ray_entity,
            ABILITY_DUPLICATOR => &mut self.duplicator_entity,
            ABILITY_MAGNET => &mut self.magnet_entity,
            ABILITY_SPIKE => &mut self.spike_entity,
            ABILITY_ENGINE => &mut self.engine_entity,
            ABILITY_TESLA => &mut self.tesla_entity,
            ABILITY_METEOR => &mut self.meteor_entity,
            ABILITY_BLACK_HOLE => &mut self.black_hole_entity,
            ABILITY_THROW => &mut self.macho_throw_entity,
            ABILITY_DRILL => &mut self.drill_entity,
            ABILITY_BEAM => &mut self.beam_entity,
            ABILITY_ROLL => &mut self.roll_entity,
            ABILITY_GUST => &mut self.gust_entity,
            ABILITY_REVIVAL => &mut self.revival_entity,
            ABILITY_PLATFORM => &mut self.circle_entity,
            ABILITY_TIME_STOP => &mut self.time_stop_entity,
            ABILITY_ROCK => &mut self.rock_entity,
            _ => return None,
        })
    }

    /// Ability.EnterAbility runs on the prefab of the slot that was cast, so
    /// that slot's collider becomes the form's row.
    fn select_form(&mut self, s: usize) {
        let row = self.form_entities[s];
        if row == usize::MAX {
            return;
        }
        if let Some(alias) = self.form_alias(self.abilities[s]) {
            *alias = row;
        }
    }

    /// The slime object is gone: eliminated, or killed after WinGame, where
    /// Player.Kill is ignored but PlayerCollision still destroys the slime.
    fn slime_destroyed(&self) -> bool {
        self.out || self.slime_gone || (self.won && !self.base.alive && self.respawn_ticks == 0)
    }

    /// Copies the per-player state (the C# Player object's, and the port's
    /// bookkeeping for it) from the player's own slot onto this body.
    fn take_player_state(&mut self, player: &PlayerSlot) {
        self.owner = player.owner;
        self.team = player.team;
        self.keyboard = player.keyboard;
        self.stocks = player.stocks;
        self.kills = player.kills;
        self.deaths = player.deaths;
        self.cause_of_death = player.cause_of_death;
        self.death_tick = player.death_tick;
        self.won = player.won;
        self.out = player.out;
        self.telemetry = player.telemetry;
        self.slime_gone = player.slime_gone;
        self.reported_position = player.reported_position;
        self.reported_tick = player.reported_tick;
        self.tie_position = player.tie_position;
        self.unpublished_tick = player.unpublished_tick;
        self.player_scale = player.player_scale;
        self.invisible = player.invisible;
        self.invisible_time = player.invisible_time;
        self.ability_time = player.ability_time;
        self.form_flags_cleared = player.form_flags_cleared;
        self.form_flag_body = player.form_flag_body;
        self.input_jump_was_down = player.input_jump_was_down;
        self.last_movement_input = player.last_movement_input;
        self.last_action = player.last_action;
        self.unspawned = player.unspawned;
        self.respawn_ticks = player.respawn_ticks;
        self.respawn_spawn_ticks = player.respawn_spawn_ticks;
        self.respawn_selected = player.respawn_selected;
        self.stock_indicator_markers = player.stock_indicator_markers;
        self.stock_death = player.stock_death;
    }

    /// Forgets the entity rows this body held.
    fn clear_entity_rows(&mut self) {
        self.drill_hitbox_entities = [[usize::MAX; 3]; 3];
        self.form_entities = [usize::MAX; 3];
        self.circle_entity = usize::MAX;
        self.rock_entity = usize::MAX;
        self.roll_entity = usize::MAX;
        self.push_entity = usize::MAX;
        self.freeze_entities = [usize::MAX; 3];
        self.freeze_entity = usize::MAX;
        self.blink_entity = usize::MAX;
        self.growth_ray_entity = usize::MAX;
        self.shrink_ray_entity = usize::MAX;
        self.duplicator_entity = usize::MAX;
        self.magnet_entity = usize::MAX;
        self.gust_entity = usize::MAX;
        self.revival_entity = usize::MAX;
        self.body_entity = usize::MAX;
        self.dash_entities = [usize::MAX; 3];
        self.dash_entity = usize::MAX;
        self.bow_entity = usize::MAX;
        self.throw_entities = [usize::MAX; 3];
        self.throw_entity = usize::MAX;
        self.mine_entity = usize::MAX;
        self.spike_entity = usize::MAX;
        self.time_stop_entity = usize::MAX;
        self.engine_entity = usize::MAX;
        self.tesla_entity = usize::MAX;
        self.meteor_entity = usize::MAX;
        self.black_hole_entity = usize::MAX;
        self.macho_throw_entity = usize::MAX;
        self.drill_entity = usize::MAX;
        self.beam_entity = usize::MAX;
    }

    /// Every collider row the slime and its ability objects own. A dead
    /// slime's rows leave DetPhysics together. PlayerCollision destroys the
    /// prefabs in `abilities` (PlayerCollision.cs:203-210), so one a pickup
    /// replaced in AddAdditionalAbility stays behind.
    fn owned_rows(&self) -> [usize; 4] {
        [
            self.body_entity,
            self.form_entities[0],
            self.form_entities[1],
            self.form_entities[2],
        ]
    }

    /// SyncPhysicsTo(AbilityExitInfo)'s UpdateScale: the kept slime radius
    /// catches up to the Player.Scale onExitAbility just gave the hurtbox.
    fn exit_slime_radius(&self) -> Fix {
        let scale = hurtbox_scale(self.player_scale);
        if scale != self.physics_scale {
            self.slime_radius * (scale / self.physics_scale)
        } else {
            self.slime_radius
        }
    }

    fn restore_slime_radius(&mut self) {
        self.base.radius = self.exit_slime_radius();
        self.physics_scale = hurtbox_scale(self.player_scale);
    }

    /// SlimeController resets a released IgnoreNextCooldown slot to its
    /// cooldown at the head of that slot's cast check, so a cast in an earlier
    /// slot returns before the later slots are reset (SlimeController.cs:
    /// 818-831). Holding the second press skips it too, allowing the
    /// just-incremented timer to pass the strict readiness comparison.
    fn reset_ignored_cooldown(&mut self, s: usize, button_down: bool) {
        let ignore_cooldown = match self.abilities[s] {
            ABILITY_REWIND => !self.rewind.rewinding && self.rewind.finish_next_tick,
            ABILITY_TELEPORT => self.teleport_ignore_cooldown[s],
            _ => false,
        };
        if ignore_cooldown && !button_down {
            self.timers[s] = self.cooldowns[s];
            if self.abilities[s] == ABILITY_REWIND {
                self.rewind.finish_next_tick = false;
            }
        }
    }

    /// A circle form's radius and FixTransform offset, which Ability scales
    /// to Player.Scale.
    fn form_circle(&self, entity: usize, radius: Fix, offset: Vec2) -> (Fix, Vec2) {
        let slot = (self.form_entities.iter())
            .position(|&form| form == entity)
            .unwrap_or(self.active_slot);
        let form = &self.forms[slot];
        if form.scale == Fix::ZERO {
            (radius, offset)
        } else {
            (form.circle_radius, form.offset)
        }
    }

    /// `potentialCollider.Scale = Player.Scale` on the active circle form
    /// (Ability.cs:105, 135).
    fn scale_form_circle(&mut self, radius: Fix, offset: Vec2) {
        let scale = self.player_scale;
        self.forms[self.active_slot].set_circle_scale_offset(scale, radius, offset);
    }

    /// The Time Stop form's CastSpell circle radius and FixTransform offset.
    fn time_stop_circle(&self, data: &data::RolloutData) -> (Fix, Vec2) {
        let form = &self.forms[self.active_slot];
        if form.scale == Fix::ZERO {
            (data.time_stop.hurtbox_radius, data.time_stop.collider_offset)
        } else {
            (form.circle_radius, form.offset)
        }
    }

    fn scale_time_stop_circle(&mut self, data: &data::RolloutData) {
        self.scale_form_circle(data.time_stop.hurtbox_radius, data.time_stop.collider_offset);
    }

    fn set_ordinary_body_scale(&mut self, scale: Fix) {
        let scale = hurtbox_scale(scale);
        // SlimeController assigns hurtBox.Scale every pass even when the
        // value is unchanged. Q32 `(One / old) * new` is not necessarily one,
        // so the collider's stored inverse extents keep drifting by raw units.
        let ratio = (Fix::ONE / self.body_collider_scale) * scale;
        self.body_inverse_extents = self.body_inverse_extents / ratio;
        self.base.collider_inverse_extents = self.body_inverse_extents;
        self.body_collider_scale = scale;
        self.base.scale = scale;
    }

    /// SlimeController.ExitAbility enters Fall and raycasts at once
    /// (SlimeController.cs:249, 263-272). A landing on this pass begins the
    /// land animation after the slime's SpriteAnimator (hierarchy 100000007,
    /// before every ability component) has already run, so it ends one tick
    /// later than a landing in PlayerPhysics.UpdateSim; `update_obs_state`
    /// adds this marker to LAND_TICKS.
    ///
    /// An airborne exit's EnterFall first runs AlignTransformAir.
    fn exit_to_fall(&mut self) {
        if !self.base.grounded {
            self.align_transform_air();
        }
        // The disabled slime's OldUpdate already passed this updater pass, so
        // its closing AlignTransformAir waits for the next one.
        self.obs_state_held_this_tick = true;
        self.obs_state = STATE_FALL;
        self.state_ticks = 1;
    }

    /// EnterFall's AlignTransformAir, against the slime's stale inputVector
    /// (SlimeController.cs:263-266, 967-982).
    fn align_transform_air(&mut self) {
        if std::mem::take(&mut self.base.was_upside_down) {
            self.facing_right = !self.facing_right;
        }
        if self.slime_input.x < -Fix::from_f32(0.02) {
            self.facing_right = false;
        } else if self.slime_input.x > Fix::from_f32(0.02) {
            self.facing_right = true;
        }
    }
}

/// Fills `order` with the slots of `pool` in Updater order: by the hierarchy
/// each object was spawned with, the slot breaking ties. Pools reuse freed
/// slots, so slot order stops tracking spawn order once one has been freed.
fn hierarchy_order<T>(order: &mut Vec<usize>, pool: &[T], hierarchy: impl Fn(&T) -> u32) {
    order.clear();
    order.extend(0..pool.len());
    order.sort_unstable_by_key(|&index| (hierarchy(&pool[index]), index));
}

/// Where DetPhysics queues a collision callback: by pair category (0
/// Circle/Circle, 1 Circle/Box, 2 Box/Box), then in SortAndSweep pair order,
/// by the later and then the earlier bounding-box minimum on the sweep axis.
type CallbackKey = (u8, SweepRank, SweepRank);

/// A hitbox's collision callback, run at its place in DetPhysics' queue.
#[derive(Clone, Copy)]
enum CallbackHit {
    /// PlayerCollision.OnCollide with a lethal hitbox.
    Kill { player: usize, killer: u32, cause: u32 },
    /// Missile.OnCollide with an explosion's box.
    MissileBlast { missile: usize },
    /// An abilityless clone's PlayerCollision.OnCollide with a lethal hitbox.
    CloneKill { clone: usize, killer: u32 },
    /// GrenadeExplode or SmokeGrenadeExplode2.OnCollide with a Tesla line or
    /// Meteor smear, once per pair.
    ItemDetonate { item: usize, count: usize },
    /// A young SpikeAttack.OnCollide with a Player-layer box.
    SpikeKnock { spike: usize, player: usize, entity: usize, point: Vec2 },
    /// SpikeAttack.OnCollide with another composite's Spike attack or
    /// RocketEngine box.
    SpikeShove { spike: usize, target: usize, target_is_spike: bool, point: Vec2 },
}

/// Per-tick working storage of `platforms_tick`/`platform_pairs` (contents
/// are meaningless between ticks; never copied by `fork_from`).
#[derive(Default)]
struct PlatformScratch {
    others: Vec<Vec2>,
    bounds: Vec<[Vec2; 2]>,
    active: Vec<usize>,
    window: Vec<usize>,
    pairs: Vec<[usize; 2]>,
    callback_colliders: Vec<RoundedRect>,
    /// The walls as the Box/RoundedRect narrow phase copies them, after the
    /// RoundedRect/RoundedRect positional corrections.
    box_callback_colliders: Vec<RoundedRect>,
    /// The walls when the Circle/RoundedRect narrow phase builds every
    /// manifold, before any of that group's corrections move them.
    circle_colliders: Vec<RoundedRect>,
    callback_tick: Option<u32>,
    /// The sweep axis DetPhysics.Simulate chose with those colliders.
    callback_sweep_x: bool,
    contacts: Vec<(usize, usize, Contact)>,
    spike_wall_contacts: Vec<(usize, usize, Contact)>,
    engine_wall_contacts: Vec<(usize, usize, Contact)>,
    /// RocketEngine and Spike attack box centres when DetPhysics took its
    /// bounding boxes, before the Box/RoundedRect group corrected them.
    engine_swept: Vec<Vec2>,
    spike_swept: Vec<Vec2>,
    rock_wall_contacts: Vec<(usize, usize, Contact)>,
    duplicated_rock_wall_contacts: Vec<(usize, usize, Contact)>,
    /// Duplicated rocks' circles after integration, before any correction.
    duplicated_rock_swept: Vec<Circle>,
    rock_spike_hits: Vec<(usize, usize, Vec2)>,
    /// Each slime's position before PlayerPhysics.LateUpdateSim follows its
    /// ground, where an older Mine's LateUpdateSim still finds it.
    before_ground_follow: [Vec2; MAX_BODIES],
    /// The owners' inputs as the clones' SlimeControllers read them this pass,
    /// held for a clone that updates ahead of the clone batch.
    clone_actions: [CAction; MAX_BODIES],
    clone_action_count: usize,
    clone_jump_pressed: [bool; MAX_BODIES],
    /// Players whose first clone to update this pass took Player.Position.
    clones_positioned: [bool; MAX_BODIES],
    /// Clones whose updaters already ran this pass, ahead of a newer
    /// TeleportIndicator.
    clones_updated_early: Vec<usize>,
    item_spike_hits: Vec<(usize, usize, Vec2)>,
    tesla_wall_contacts: Vec<(usize, usize, Contact)>,
    /// Portal shots' wall manifolds: (shot, wall, contact).
    portal_shot_wall_contacts: Vec<(usize, usize, Contact)>,
    item_order: Vec<usize>,
    item_window: Vec<usize>,
    item_contacts: Vec<(usize, usize, Contact)>,
    item_platform_contacts: Vec<(usize, usize, Contact)>,
    /// Smoke grenades an active grapple hook touched this pass.
    hook_smoke_hits: Vec<usize>,
    /// Smoke clouds that already updated this pass, ahead of a younger
    /// Teleport marker or stock-respawned slime.
    smoke_updated_early: Vec<(usize, u32)>,
    /// Sweep keys of the wall manifolds resolved as one batch: the
    /// Circle/RoundedRect group's, or the Box/RoundedRect group's.
    circle_wall_order: Vec<(SweepRank, SweepRank, u8, usize)>,
    pickup_order: Vec<usize>,
    pickup_window: Vec<usize>,
    pickup_contacts: Vec<(usize, usize, Contact)>,
    /// Guided-Missile Box/Box manifolds. Every manifold is captured before
    /// either Missile callback destroys a participant.
    missile_contacts: Vec<(usize, usize, Contact)>,
    /// This pass's hitbox callbacks, run together by `run_callback_hits`.
    callback_hits: Vec<(CallbackKey, CallbackHit)>,
    missile_detonations: Vec<usize>,
    /// Arrow Circle/RoundedRectangle manifolds of one DetPhysics pass, in
    /// resolution order.
    arrow_platform_contacts: Vec<(usize, usize, Contact)>,
    /// Slime-vs-slime shoves of one DetPhysics pass: (pushed, other, lower id).
    slime_shoves: Vec<(usize, usize, bool)>,
    /// This pass's Player.Scale changes by a ScaleChanger, in hierarchy order:
    /// (player, changer hierarchy, scale before).
    player_scale_changes: Vec<(usize, u32, Fix)>,
    /// This pass's platforms before a spawned ScaleChanger or
    /// DuplicatePlatformEffect resized them: (platform, updater hierarchy,
    /// shape before).
    platform_resizes: Vec<(usize, u32, Platform)>,
    /// Grounded slimes a wall squished this pass, in callback order:
    /// (abilityless clone, player or clone index).
    squished: Vec<(bool, usize)>,
    /// Ropes below this hierarchy have run their UpdateSim this pass.
    ropes_updated_below: u32,
    /// Ropes below this hierarchy ran ahead of a later-instantiated player
    /// object this pass.
    ropes_ran_below: u32,
    /// The oldest hammer's hierarchy: ropes from here up update in the hammer
    /// loop, and their attachments pull after them.
    ropes_deferred_from: u32,
    /// Tacks below this hierarchy ran their UpdateSim ahead of a
    /// later-instantiated player object this pass.
    tacks_ran_below: u32,
    /// Mjolnir hammers below this hierarchy ran their UpdateSim ahead of a
    /// later-instantiated player object this pass.
    hammers_ran_below: u32,
    /// The row hierarchies of the Duplicator copies the current Duplicated
    /// platform pass runs; None runs them all.
    duplicates_window: Option<std::ops::Range<u32>>,
    /// Rocket engines below this hierarchy ran ahead of a later-instantiated
    /// player object this pass.
    engines_ran_below: u32,
    /// Likewise for the Spawned platform pass, and the hierarchy below which
    /// its platforms have already updated this pass.
    spawned_window: Option<std::ops::Range<u32>>,
    spawned_platforms_below: u32,
    /// Set while the ropes waiting on a platform's ScaleChanger run.
    ropes_changer_pass: bool,
    /// Sorted collider query output shared by Dash, Meteor and Roll, retained
    /// across casts so the hot rollout never allocates for source collider lists.
    ray_hits: Vec<SortedRayHit>,
    duplicate_shake_order: Vec<(u32, u8, usize)>,
    duplicate_shake_offsets: Vec<(u8, usize, Vec2)>,
    /// Objects awaiting their Init: (hierarchy base, kind, index into its
    /// list; 3 * player + slot for a picked ability).
    pending_objects: Vec<(u32, PendingObject, usize)>,
}

#[derive(Clone, Copy)]
enum PendingObject {
    Arrow,
    DuplicatedPickup,
    AbilitylessClone,
    BlackHole,
    DuplicatedRock,
    ClappedBlackHole,
    PickedAbility,
    Mine,
    GuidedMissile,
    MissileExplosion,
    RevivalMarker,
    TeleportMarker,
    TeslaLine,
    GrenadeExplosion,
    SmokeCloud,
    SmokeExplosion,
}

impl PlatformScratch {
    /// Whether DetPhysics' broadphase pairs the circle with the platform. The
    /// sweep takes its bounding boxes before this pass's platform/platform
    /// corrections move the wall, so a correction toward the circle does not
    /// make a pair.
    fn swept_pairs(&self, tick: u32, index: usize, circle: Circle) -> bool {
        let Some(swept) = self
            .callback_colliders
            .get(index)
            .filter(|_| self.callback_tick == Some(tick))
        else {
            return true;
        };
        let extent = Vec2::new(
            swept.inner.right.x.abs() + swept.inner.up.x.abs() + swept.radius,
            swept.inner.right.y.abs() + swept.inner.up.y.abs() + swept.radius,
        );
        let (low, high) = (swept.inner.center - extent, swept.inner.center + extent);
        circle.center.x + circle.radius > low.x
            && circle.center.x - circle.radius < high.x
            && circle.center.y + circle.radius > low.y
            && circle.center.y - circle.radius < high.y
    }
}

#[derive(Clone, Copy, Default)]
struct SortedRayHit {
    distance: Fix,
    hierarchy: u32,
    /// Query-specific collider class used as the primary stable sort key.
    kind: u8,
    index: usize,
}

pub struct RolloutWorld {
    pub valid: bool,
    pub failed: bool,
    pub started: bool,
    pub terminal: bool,
    pub map: usize,
    pub stocks: u32,
    pub warmup: u32,
    pub limit: u32,
    pub tick: u32,
    pub episode_ticks: u32,
    pub rng: Random,
    pub players: Vec<PlayerSlot>,
    /// Players in the session; `players` holds their own slots first, then any
    /// extra bodies.
    pub player_count: usize,
    /// A player slot as the episode built it, before any pass: the fresh
    /// body a promoted abilityless clone starts from.
    pub body_template: Option<Box<PlayerSlot>>,
    pub platforms: Vec<Platform>,
    /// Raycast broad phase over `platforms` (`rebuild_bounds`).
    pub bounds: PlatformBounds,
    /// Incremented by every mutation of `platforms`/`platform_dynamics`
    /// (`platforms_changed`). The derived data below is refreshed only when
    /// its recorded epoch differs, so an undisturbed level costs nothing per
    /// tick.
    platform_epoch: u64,
    /// `platform_epoch` the broad phase was built for.
    bounds_epoch: u64,
    /// `platform_epoch` the platform entity rows were written for.
    platform_rows_epoch: u64,
    /// `platform_epoch` at which `platforms_tick` last found every body at
    /// rest at its home, so the check need not be repeated until a change.
    quiet_epoch: u64,
    /// Buffers of the platform physics stage, kept between ticks so a level
    /// with moving platforms does not allocate on every tick.
    scratch: PlatformScratch,
    /// Parallel to `platforms`: rigid body and home spring state.
    pub platform_dynamics: Vec<PlatformDynamics>,
    /// Parallel to `platforms`: index into the map's PlatformDef list, or
    /// usize::MAX for spawned (ability) platforms.
    pub platform_defs: Vec<usize>,
    /// Parallel to `platforms`: index into the entity table.
    pub platform_entities: Vec<usize>,
    pub arrows: Vec<Arrow>,
    pub ability_pickups: Vec<AbilityPickup>,
    /// Pure tick-indexed DynamicAbilityPickup wobble values. Kept across
    /// episode resets so repeated matches do not redo identical Q32 sine
    /// interpolation.
    pickup_wobble_cache: Vec<Fix>,
    pub black_holes: Vec<BlackHoleState>,
    /// Duplicated holes waiting for BlackHole.Init on the next pass.
    pub pending_black_holes: Vec<BlackHoleState>,
    pub duplicated_rocks: Vec<DuplicatedRock>,
    /// Duplicated rocks whose circles register on the next pass.
    pub pending_duplicated_rocks: Vec<DuplicatedRock>,
    pub abilityless_clones: Vec<AbilitylessClone>,
    pub macho_boulders: Vec<MachoBoulder>,
    pub thrown_items: Vec<ThrownItem>,
    pub guided_missiles: Vec<GuidedMissile>,
    pub missile_explosions: Vec<MissileExplosion>,
    pub grenade_explosions: Vec<GrenadeExplosion>,
    pub smoke_clouds: Vec<SmokeCloud>,
    pub smoke_explosions: Vec<SmokeExplosion>,
    pub time_stop_effects: Vec<TimeStopEffect>,
    pub spike_attacks: Vec<SpawnedSpike>,
    pub engines: Vec<SpawnedEngine>,
    pub tesla_nodes: Vec<SpawnedTeslaNode>,
    pub destroyed_tesla_lines: Vec<DestroyedTeslaLine>,
    pub retired_tesla_contacts: Vec<SpawnedTeslaNode>,
    pub meteor_smears: Vec<MeteorSmear>,
    pub meteor_waves: Vec<Shockwave>,
    pub frozen_solids: Vec<FrozenSolidState>,
    pub scale_changers: Vec<ScaleChangerState>,
    pub player_time_scale: Fix,
    pub time_stop_protected: [bool; MAX_BODIES],
    pub spawned: Vec<SpawnedPlatform>,
    /// Black Hole pulls on a shrinking platform whose ResizablePlatform ran
    /// earlier in the pass: (platform, vector, distance cubed, hole mass,
    /// Push-controlled). They read the mass the shrink leaves.
    pub late_platform_pulls: Vec<(usize, Vec2, Fix, Fix, bool)>,
    pub gust_waves: [Shockwave; MAX_BODIES * 3],
    pub revival_marker_pool: Vec<RevivalMarker>,
    pub teleport_marker_pool: Vec<TeleportMarker>,
    pub portal_shots: Vec<PortalShotState>,
    pub blink_object_tunnels: Vec<BlinkObjectTunnel>,
    pub teleport_object_effects: Vec<TeleportObjectEffect>,
    pub portals: Vec<PortalEndpoint>,
    /// `[bluePortal, orangePortal]` of each PortalGun a pickup replaced while
    /// its shots were in flight. AddAdditionalAbility only drops the
    /// reference, so the gun lives on and those shots still land through it.
    pub orphan_portal_guns: Vec<[Option<usize>; 2]>,
    pub beam_orbs: Vec<BeamOrbState>,
    pub beam_pool: Vec<BeamPoolSlot>,
    /// Fixed-capacity DetPhysics RopeBody pool and its ability-owned
    /// attachments. Every slot owns its 40 segments and 32 contacts up front.
    pub(crate) ropes: Vec<rope_abilities::RolloutRope>,
    pub(crate) next_rope_number: u32,
    rope_rectangles: Vec<RoundedRect>,
    beam_graph: crate::beam::graph::Graph,
    beam_snapshot: crate::beam::graph::Snapshot,
    beam_inputs: Vec<crate::beam::graph::Beam>,
    /// Per collider-body portal hysteresis. Active portal pool indices are
    /// reused and fit in one word (six players * three slots * two mouths).
    pub portal_body_inside: Vec<u64>,
    pub portal_body_ids: Vec<u32>,
    duplicate_platform_effects: Vec<DuplicatePlatformState>,
    /// `GameSessionHandler.SuddenDeathInProgress`. `WinGame` and
    /// `DeclareGameUndecided` both call `ActivateSuddenDeath(activate: false)`
    /// (GameSessionHandler.cs:655, 548), so this drops back to false on the
    /// pass that resolves the round - before the authored level updaters run,
    /// which is what lets map 2's `AntiLockPlatform` orbit resume for that one
    /// tick.
    pub sudden_death: bool,
    /// `AnimateVelocity.inSuddenDeath`, the per-component latch. Nothing ever
    /// calls `ActivateSuddenDeath(false)` on the component, so the level keeps
    /// sinking after the round is decided even though the global flag is down.
    pub sudden_death_latched: bool,
    /// `GameSessionHandler.gameInProgress`. Cleared by `prepareNextlevel`
    /// through `WinGame`/`DeclareGameUndecided`; it is what stops
    /// `UpdateSim` from immediately re-arming sudden death on the next pass.
    pub game_in_progress: bool,
    pub sudden_death_tick: u32,
    pub ability_spawner_enabled: bool,
    /// Per-authored-spawner `(time, spawn_count)` state, in updater order.
    pub ability_spawner_state: Vec<(Fix, u8)>,
    /// Abilities which can still own an updater in this episode. Bits are
    /// retained after a pickup replaces a loadout slot because already-fired
    /// projectiles and effects remain in Unity's updater list.
    active_subsystems: u64,
    /// AntiLockPlatform runtime: platform index and current waypoint.
    pub orbits: Vec<(usize, usize)>,
    /// Authored VectorFieldPlatform indices. Empty on maps without the component.
    pub vector_fields: Vec<usize>,
    /// GameSessionHandler level-intro routine state. Phase 0 is its 0.1 s
    /// delay, phase 1 animates, phase 2 is the queued enable callback, and 3
    /// is complete. These vectors are empty-cost after reset and only affect
    /// the warmup path.
    pub intro_random_delays: Vec<Fix>,
    pub intro_phase: u8,
    pub intro_progress: Fix,
    pub intro_delay_elapsed: Fix,
    pub intro_contacts_pending: bool,
    pub next_platform_id: u32,
    pub next_entity_id: u32,
    /// Published id per internal entity id (0 = not yet observed), and the
    /// last one handed out. See `number_observed`.
    pub observed_ids: Vec<u32>,
    pub last_observed_id: u32,
    /// Base hierarchy for the next prefab instantiated after player spawn.
    pub next_spawn_hierarchy: u32,
    /// Instantiations made during the updater phase by objects this port
    /// updates out of hierarchy order, as (object hierarchy, updatables).
    /// Updater runs them in hierarchy order, so a spawn by a lower object
    /// claims its hierarchy first.
    pub queued_spawns: Vec<(u32, u32)>,
    // Observation buffers. `entities`/`slimes` back the pointers in `state`.
    pub entities: Vec<CEntity>,
    pub slimes: Vec<CSlime>,
    pub state: Box<CState>,
    /// Emitted rows (the fixed table minus `E_REMOVED` entries).
    pub state_entities: Vec<CEntity>,
    pub sample_entities: Vec<CEntity>,
    pub sample_slimes: Vec<CSlime>,
    pub sample: Box<CState>,
    pub sample_valid: bool,
    /// Registered actions per simulated tick (warmup included), for the
    /// BOPLREP2 replay export.
    recording: Vec<RecordedActions>,
    /// Config captured at reset for the replay header.
    pub replay_config: CConfig,
    /// Encoded replay archive (bopl_rl_replay hands out this buffer).
    pub replay_buffer: Vec<u8>,
    pub error: [u8; 512],
}

fn empty_state() -> Box<CState> {
    Box::new(CState {
        header: CHeader::default(),
        players: [CPlayer::default(); 6],
        entities: core::ptr::null(),
        slimes: core::ptr::null(),
        telemetry: [CTelemetry::default(); 6],
    })
}

/// Beam's water reflection tests Constants.WATER_HEIGHT and skips it on a
/// space level (Beam.cs:446, 604).
fn new_beam_graph(data: &data::RolloutData, space: bool) -> crate::beam::graph::Graph {
    crate::beam::graph::Graph::new(crate::beam::graph::Config {
        maximum: data.beam.maximum_distance,
        water: Fix::from_f32(-11.22),
        space,
        mask: data.beam.hit_mask,
        cross_offset: data.beam.cross_offset,
        environmental_player: 1000,
    })
}

