    #[test]
    fn ray_point_query_uses_last_overlapping_rounded_rect() {
        let mut world = RolloutWorld::new();
        world.reset(&test_config()).unwrap();
        let center = Vec2::new(Fix::ZERO, Fix::from_int(30));
        let _first = world.spawn_ability_platform(0, center, Fix::ONE);
        let last = world.spawn_ability_platform(1, center, Fix::ONE);
        world.refresh_platform_entities();
        let selected = world
            .entities
            .iter()
            .enumerate()
            .rfind(|(_, row)| {
                row.kind == 2
                    && row.flags & E_ACTIVE != 0
                    && RolloutWorld::entity_rounded_rect(**row)
                        .is_some_and(|shape| shape.overlaps(center))
            })
            .map(|(entity, _)| entity);
        assert_eq!(selected, Some(world.platform_entities[last]));

        world.shoot_scale_ray(center, Vec2::RIGHT, 0, true, data::get());

        assert!(
            world.scale_changers.iter().any(|effect| {
                effect.active && effect.target_kind == 2 && effect.victim == last
            })
        );
    }

    #[test]
    fn generic_scale_changers_share_live_entity_scale() {
        let mut world = RolloutWorld::new();
        world.reset(&test_config()).unwrap();
        let entity = world.entities.len();
        let id = world.next_id();
        world.entities.push(CEntity {
            id,
            kind: 0,
            layer: 10,
            flags: E_ACTIVE | E_ENABLED,
            radius: Fix::ONE.raw(),
            inverse_mass: (-Fix::ONE).raw(),
            ..CEntity::default()
        });

        world.begin_scale_change_entity(entity, true, 1);
        world.scale_changers[0].active = false;
        world.scale_changers[0].current_scale = Fix::from_int(2);
        world.begin_scale_change_entity(entity, true, 1);
        assert_eq!(world.scale_changers[0].current_scale, Fix::from_int(2));

        world.begin_scale_change_entity(entity, false, 1);
        assert_eq!(world.scale_changers.len(), 2);
        world.tick += 1;
        world.scale_changers_tick(data::get(), DT, None, None);
        assert_eq!(
            world.scale_changers[0].current_scale,
            world.scale_changers[1].current_scale
        );
    }

