    #[test]
    fn magnet_pulls_holds_and_fires_spell_markers() {
        let mut world = RolloutWorld::new();
        let mut config = test_config();
        config.player[0].abilities[0] = ABILITY_MAGNET;
        world.reset(&config).unwrap();
        let data = data::get();
        world.players[0].active = ActiveAbility::Magnet;
        world.players[0].magnet.phase = 2;
        world.players[0].magnet.aim = Vec2::RIGHT;
        world.players[0].magnet.body_right = Vec2::RIGHT;
        let firepoint = world.magnet_firepoint(0, data);
        world.revival_marker_pool.push(RevivalMarker {
            active: true,
            registered: true,
            position: firepoint,
            body: data.revival.marker_body,
            scale: Fix::from_int(2),
            magnet_hold_ticks: -1,
            ..RevivalMarker::default()
        });
        world.teleport_marker_pool.push(TeleportMarker {
            active: true,
            registered: true,
            position: firepoint + Vec2::RIGHT,
            body: data.teleport.marker_body,
            scale: Fix::from_int(3),
            magnet_hold_ticks: -1,
            ..TeleportMarker::default()
        });

        world.magnet_pull(0, data);
        assert!(world.revival_marker_pool[0].body.force.x < Fix::ZERO);
        assert!(world.teleport_marker_pool[0].body.force.x < Fix::ZERO);
        world.revival_marker_pool[0].body.force = Vec2::ZERO;
        world.teleport_marker_pool[0].body.force = Vec2::ZERO;

        world.magnet_try_pickup_item(0, data);
        assert_eq!(world.players[0].magnet.held, MagnetHeld::RevivalMarker(0));
        world.magnet_update_held_item(0, data);
        assert_eq!(world.revival_marker_pool[0].magnet_holder, Some(0));
        world.magnet_fire_held_item(0, Vec2::RIGHT, data);
        assert_eq!(
            world.revival_marker_pool[0].body.force,
            Vec2::RIGHT * data.magnet.fire_force * Fix::from_int(2)
        );

        world.players[0].magnet.phase = 2;
        world.magnet_take_target(0, MagnetHeld::TeleportMarker(0), data);
        world.magnet_update_held_item(0, data);
        world.magnet_fire_held_item(0, Vec2::RIGHT, data);
        assert_eq!(
            world.teleport_marker_pool[0].body.force,
            Vec2::RIGHT * data.magnet.fire_force
        );
    }

    #[test]
    fn blink_routes_abilityless_clone_through_player_tunnel() {
        let mut world = RolloutWorld::new();
        world.reset(&test_config()).unwrap();
        let data = data::get();
        world.duplicate_player_target(1, Vec2::ZERO, Vec2::UP, data);
        world.tick += 1;
        world.register_pending_objects(data);
        let entity = world.abilityless_clones[0].entity.unwrap();
        for row in &mut world.entities {
            row.flags = 0;
        }
        world.entities[entity].flags = E_ACTIVE | E_ENABLED | E_TRIGGER;
        let position = world.abilityless_clones[0].base.position;
        // An idle slime's body is live whatever its row says; lift the
        // duplicated slime off the ray so only its clone is in the way.
        world.players[1].base.position += Vec2::UP * Fix::from_int(10);
        world.players[1].base.sync_collider();

        world.shoot_blink_ray(
            position - Vec2::RIGHT * Fix::from_int(10),
            Vec2::RIGHT,
            0,
            data,
        );

        assert!(world.abilityless_clones[0].blink_tunnel_active);
        assert!(world.blink_object_tunnels.is_empty());
        assert_eq!(
            world.players[0].cooldowns[world.players[0].active_slot],
            data.blink.on_player_hit_cooldown
        );
        assert_eq!(world.entities[entity].flags & E_ACTIVE, 0);

        for _ in 0..100 {
            world.tick += 1;
            world.blink_clone_tunnels_tick(data, DT);
            if !world.abilityless_clones[0].blink_tunnel_active {
                break;
            }
        }
        assert!(!world.abilityless_clones[0].blink_tunnel_active);
        assert_ne!(world.entities[entity].flags & E_ACTIVE, 0);
        assert!(world.abilityless_clones[0].blink_tunnel_released);
    }

