    #[test]
    fn instant_ability_cast_freezes_the_state_machine_for_its_tick() {
        let mut world = RolloutWorld::new();
        let mut config = test_config();
        for player in &mut config.player {
            player.abilities[0] = ABILITY_TELEPORT;
        }
        world.reset(&config).unwrap();
        world.players[0].obs_state = STATE_IDLE;
        world.players[0].state_ticks = 0;
        world.players[0].facing_right = true;
        world.players[0].timers[0] = Fix::from_int(100);

        world.player_tick(
            0,
            Action {
                buttons: 2,
                ..Action::default()
            },
            Vec2::ZERO,
            false,
            data::get(),
        );
        // SlimeController.OldUpdate returned right after EnterAbility, and an
        // instant ability leaves no form behind to freeze the switch later.
        assert!(world.players[0].active == ActiveAbility::None);
        assert!(world.players[0].obs_state_held_this_tick);

        world.update_obs_state(0, Vec2::RIGHT);
        assert_eq!(world.players[0].obs_state, STATE_IDLE);
        assert!(!world.players[0].obs_state_held_this_tick);

        // The next tick is an ordinary one again.
        world.update_obs_state(0, Vec2::RIGHT);
        assert_eq!(world.players[0].obs_state, STATE_RUN);
    }

    #[test]
    fn fifth_engine_cast_uses_temporary_five_child_mass() {
        let mut world = RolloutWorld::new();
        world.reset(&test_config()).unwrap();
        let data = data::get();
        world.players[0].active = ActiveAbility::Engine;
        world.players[0].active_slot = 0;

        for tick in 1..=data.engine.buffer_size {
            world.tick = tick as u32;
            assert!(world.spawn_engine(0, data));
        }
        let platform_index = world
            .platforms
            .iter()
            .position(|p| Some(p.id) == world.players[0].base.ground)
            .unwrap();
        let before = world.platform_dynamics[platform_index].body;
        let five_child_inverse_mass = Fix::ONE
            / (Fix::ONE / before.inverse_mass + Fix::ONE / data.engine.rocket_body.inverse_mass);
        let body_position = world.players[0].base.position;
        let normal = world.platforms[platform_index]
            .surface
            .normal(body_position);

        world.tick += 1;
        assert!(world.spawn_engine(0, data));

        assert_eq!(
            world.platform_dynamics[platform_index].body.velocity,
            before.velocity + five_child_inverse_mass * (-normal * data.engine.cast_force)
        );
        assert_eq!(
            world
                .engines
                .iter()
                .filter(|engine| engine.active && engine.owner == 0)
                .count(),
            data.engine.buffer_size
        );
    }

